(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.016-t*0.22)*16 + Math.sin(x*0.02+t*0.3)*11;
  const w2x = Math.sin((x+y)*0.012+t*0.4)*8 + Math.cos((x-y)*0.01-t*0.35)*6;
  const w2y = Math.cos((x-y)*0.014+t*0.38)*9 + Math.sin((x+y)*0.011-t*0.42)*7;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.45+2)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*55, 0.065, 2.4, 1.15],
    [200+Math.sin(t*0.42+6)*110, 220+Math.cos(t*0.32+3)*65, 0.095, 1.8, 0.9],
    [300+Math.cos(t*0.48+2)*85, 30+Math.sin(t*0.62+5)*45, 0.075, 2.2, 1.0]
  ];
  let aS=0, iS=0, mS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    mS += Math.sin(d*f*1.3 - t*sp*0.8 + 3.0) * w * 0.5;
  }
  const tw = 10;
  const act=aS/tw, inh=iS/tw, mod=mS/tw;
  const bg1 = Math.sin(sx*0.04+sy*0.025+t*0.8);
  const bg2 = Math.sin(sx*0.03-sy*0.04+t*1.1);
  const bg3 = Math.sin((sx+sy)*0.12+t*2.5)*0.2;
  const bg4 = Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg5 = Math.sin(sx*0.07+t*0.5)*Math.cos(sy*0.06-t*0.4)*0.3;
  const bg = (bg1+bg2)/2 + bg3+bg4+bg5;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.03-ang*2+t*0.8)*0.5;
  const spiral = (sp1+sp2)*0.4 + sp3;
  const flow = Math.sin(ang*2+dist*0.02+t*0.7)*Math.cos(ang*3-dist*0.015-t*0.5)*0.3;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const rd2 = Math.tanh((mod*0.6 - act*0.4 + flow)*1.8);
  const cross = Math.tanh((rd1*0.7 + rd2*0.5 + bg*0.15)*1.6);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const voronoi = Math.sin(Math.floor(sx/20)*1.7+Math.floor(sy/20)*2.3+t*0.4)*0.15;
  const blend = cross*0.6 + cell*0.2 + voronoi*0.1 + spiral*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,55],[12,45,95],[18,95,120],[25,155,145],[80,185,130],
    [180,195,80],[220,165,55],[215,110,65],[175,55,70],[110,28,65],
    [55,15,55],[5,12,55]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85 + Math.sin(cross*Math.PI)*0.15;
  const edge = Math.abs(cross)>0.65 ? 1.12 : 1.0;
  const glow = Math.max(0, 1-Math.abs(cross)*2)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*80)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*120)|0)
  ];
}
